#!/usr/bin/env python3
import sys
import os
import requests

def query_wolfram(query):
    app_id = os.environ.get('WOLFRAM_APP_ID', '')
    if not app_id:
        print("Error: WOLFRAM_APP_ID not set")
        return None

    url = "https://api.wolframalpha.com/v1/simple"
    params = {
        'appid': app_id,
        'i': query
    }

    response = requests.get(url, params=params)
    if response.status_code == 200:
        return response.text
    else:
        print(f"Error: {response.status_code}")
        return None

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python3 wolfram_query.py <query>")
        sys.exit(1)

    query = ' '.join(sys.argv[1:])
    result = query_wolfram(query)
    if result:
        print(result)
EOF
